CREATE POLICY recurring_expenses_select ON public.recurring_expenses FOR SELECT TO authenticated USING (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid())); CREATE POLICY recurring_expenses_insert ON public.recurring_expenses FOR INSERT TO authenticated WITH CHECK (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid()) AND created_by = auth.uid()); CREATE POLICY recurring_expenses_update ON public.recurring_expenses FOR UPDATE TO authenticated USING (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid())) WITH CHECK (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid())); CREATE POLICY recurring_expenses_delete ON public.recurring_expenses FOR DELETE TO authenticated USING (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid()));